272		none := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{})]
273		if none.Labels == nil {
274			t.Fatal("query labels for unlabeled series must be non-nil empty map")
275		}
276		none.Labels["host"] = "x"
277		none.Count = 41
278		none.Average = 42
279	
280		emptyVal := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"zone": ""})]
281		delete(emptyVal.Labels, "zone")
282		emptyVal.Count = 5
283		emptyVal.Average = 9
284	
285		// 整理结果中的序列条目：反转顺序、截断并追加伪造条目、篡改信封字段。
286		for i, j := 0, len(q1.Series)-1; i < j; i, j = i+1, j-1 {
287			q1.Series[i], q1.Series[j] = q1.Series[j], q1.Series[i]
288		}
289		q1.Series = append(q1.Series[:1], QuerySeries{Name: "ghost", Labels: map[string]string{}, Count: 1})
290		q1.Status = "mutated"
291		q1.Op = "mutated"
292	
293		// 另一份此前取得的查询结果不被污染。
294		assertFullCPUResult(t, q0)
295		// 之后取得的查询结果仍按存储事实返回。
296		q2 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
297		assertFullCPUResult(t, q2)
