352		}
353		if len(qAllBefore.Series) != 2 {
354			t.Fatalf("retained full query baseline = %+v, want 2 series", qAllBefore.Series)
355		}
356	
357		// 向 host=a 写入新时间戳 3000->6：average 变为 (2+4+6)/3 = 4。
358		write := mustOK(t, s, `[{"name":"cpu","timestamp":3000,"value":6,"labels":{"host":"a"}}]`)
359		if write.Added != 1 || write.Duplicates != 0 {
360			t.Fatalf("new timestamp write = %+v, want added=1", write)
361		}
362	
