package darksafe

import "testing"

func TestTempProcessLineNilContract(t *testing.T) {
	s := NewMetricStore()

	// 成功写入：非 nil *BatchResult，无错误。
	r, lerr := s.ProcessLine(`[{"name":"cpu","timestamp":1000,"value":2}]`)
	if lerr != nil || r == nil {
		t.Fatalf("initial write: r=%v lerr=%+v", r, lerr)
	}
	if _, ok := r.(*BatchResult); !ok {
		t.Fatalf("initial write type = %T", r)
	}

	// 冲突批次：先给 2000 新增 4，再把 1000 改成 9。
	r, lerr = s.ProcessLine(`[
		{"name":"cpu","timestamp":2000,"value":4},
		{"name":"cpu","timestamp":1000,"value":9}
	]`)
	if r != nil {
		t.Fatalf("failed batch must return true nil, got %T: %+v", r, r)
	}
	if lerr == nil || lerr.Index != 2 || lerr.Conflict == nil {
		t.Fatalf("want index-2 conflict, got %+v", lerr)
	}
	c := lerr.Conflict
	if c.Series.Name != "cpu" || c.Timestamp != 1000 || c.Existing != 2 || c.Submitted != 9 {
		t.Fatalf("conflict payload = %+v", c)
	}

	// 数据状态：2000 不留点，1000 仍为 2。
	r, lerr = s.ProcessLine(`{"op":"query","name":"cpu","start":0,"end":10000}`)
	if lerr != nil || r == nil {
		t.Fatalf("query: %v %+v", r, lerr)
	}
	qr := r.(*QueryResult)
	if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
		t.Fatalf("post-conflict query = %+v", qr.Series)
	}

	// 查询失败：倒置区间，返回 true nil 且不改数据。
	r, lerr = s.ProcessLine(`{"op":"query","name":"cpu","start":9,"end":1}`)
	if r != nil {
		t.Fatalf("failed query must return true nil, got %T", r)
	}
	if lerr == nil || lerr.Index != 0 || lerr.Conflict != nil {
		t.Fatalf("inverted range error = %+v", lerr)
	}

	// 字段错误保留采样点位置。
	r, lerr = s.ProcessLine(`[{"name":"cpu","timestamp":2000,"value":"oops"}]`)
	if r != nil || lerr == nil || lerr.Index != 1 {
		t.Fatalf("field error = %v %+v", r, lerr)
	}

	// 整行解析失败：true nil。
	r, lerr = s.ProcessLine(`not json`)
	if r != nil || lerr == nil || lerr.Index != 0 {
		t.Fatalf("parse error = %v %+v", r, lerr)
	}

	// 空数组仍是成功写入；无命中查询仍是成功查询。
	r, lerr = s.ProcessLine(`[]`)
	if lerr != nil {
		t.Fatalf("empty array: %+v", lerr)
	}
	if br, ok := r.(*BatchResult); !ok || br.Added != 0 {
		t.Fatalf("empty array result = %T %+v", r, r)
	}
	r, lerr = s.ProcessLine(`{"op":"query","name":"nope","start":0,"end":1}`)
	if lerr != nil {
		t.Fatalf("empty-match query: %+v", lerr)
	}
	if qr2, ok := r.(*QueryResult); !ok || len(qr2.Series) != 0 {
		t.Fatalf("empty-match query result = %T %+v", r, r)
	}
}

